<span class="line"><span class="__shiki_1itgoe">        return</span><span class="__shiki_140thh"> num </span><span class="__shiki_1itgoe">*</span><span class="__shiki_1t8gfj"> factorial</span><span class="__shiki_140thh">(num </span><span class="__shiki_1itgoe">-</span><span class="__shiki_dzsirb"> 1</span><span class="__shiki_140thh">)</span></span>
