<span class="line"><span class="__shiki_140thh">    components.</span><span class="__shiki_1t8gfj">push</span><span class="__shiki_140thh">(</span><span class="__shiki_1itgoe">new</span><span class="__shiki_1t8gfj"> BaseComponent</span><span class="__shiki_140thh">())</span></span>
